        window = tailWord >>> (bitsRead - tailBase * 8);
      }
      v = window & 0x1fff;
      bitsRead += 13;
      value.items[i0] = v;
    }
  }
  if (bitsRead + 3 > numBits) {
    return false;
  }
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0x7;
  bitsRead += 3;
  if (v > 4) {
    return false; // the length guards the slice — reject, never clamp
  }
  value.sLength = v;
  {
    final pad = bitsRead & 7;
    if (pad != 0) {
      if (bitsRead + (8 - pad) > numBits) {
        return false;
      }
      if (view.getUint8(bitsRead >>> 3) >>> pad != 0) {
        return false; // nonzero padding is refused (SPEC §4.3)
      }
      bitsRead += 8 - pad;
    }
  }
  if (bitsRead + value.sLength * 8 > numBits) {
    return false;
  }
  {
    final base = bitsRead >>> 3;
    for (var i0 = 0; i0 < value.sLength; i0++) {
      value.s[i0] = view.getUint8(base + i0);
    }
  }
  bitsRead += value.sLength * 8;
  for (var i0 = 0; i0 < value.sLength; i0++) {
    if (value.s[i0] == 0) {
      return false; // an interior null is content the read refuses (SPEC §4.7)
    }
  }
  if (bitsRead + 84 > numBits) {
    return false;
  }
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0xffffffff;
  bitsRead += 32;
  value.p = v;
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0x1fffffff;
  bitsRead += 29;
  value.q = v;
  v = (window >>> 29) & 0x7ffff;
  bitsRead += 19;
  value.r = v;
  v = (window >>> 48) & 0xf;
  bitsRead += 4;
  value.tail = v;
  return true;
}

// measureRegainAfterAlign is the exact wire bits writeRegainAfterAlign would produce for value —
// trusted like the writer; static runs fold to literals at generation time.
int measureRegainAfterAlign(RegainAfterAlign value) {
  var bits = 0;
  bits += 7;
  bits += value.itemsCount * 13;
  bits += 3;
  bits += (8 - (bits & 7)) & 7;
  bits += value.sLength * 8;
  bits += 84;
  return bits;
}
